import{_ as e,a as r,b as a}from"./chunks/settings-3.DZodn8Ge.js";import{_ as s,o,c as n,a2 as d}from"./chunks/framework.Bzj1XTnB.js";const b=JSON.parse('{"title":"Settings","description":"Every app setting, what it does and its default.","frontmatter":{"lang":"en","slug":"settings","order":10,"title":"Settings","description":"Every app setting, what it does and its default."},"headers":[],"relativePath":"settings.md","filePath":"settings.md"}'),i={name:"settings.md"};function h(l,t,g,u,c,p){return o(),n("div",null,[...t[0]||(t[0]=[d('<h1 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h1><p>Open <strong>Settings</strong> from the bottom bar, the side menu or the pink circle at the top of the home screen.</p><p><img src="'+e+'" alt="Settings"></p><p>At the top you can <strong>Rate us</strong> and <strong>Share app</strong>.</p><h2 id="appearance" tabindex="-1">Appearance <a class="header-anchor" href="#appearance" aria-label="Permalink to &quot;Appearance&quot;">​</a></h2><ul><li><strong>Theme</strong> — System, Light or Dark.</li><li><strong>Status bar icons</strong> — Auto (dark or light, whichever shows on the canvas), always dark or always light.</li><li><strong>Hide status bar while drawing</strong> — more room for the canvas. Swipe down from the top to see it for a moment.</li></ul><h2 id="drawing" tabindex="-1">Drawing <a class="header-anchor" href="#drawing" aria-label="Permalink to &quot;Drawing&quot;">​</a></h2><p><img src="'+r+'" alt="Drawing and canvas settings"></p><table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th><th>Default</th></tr></thead><tbody><tr><td><strong>Stylus pressure</strong></td><td>Pressing harder with a pen draws thicker</td><td>On</td></tr><tr><td><strong>Touch sensitivity</strong></td><td>Soft, Medium or Firm — how hard you need to press</td><td>Medium</td></tr><tr><td><strong>Minimum pressure</strong></td><td>The lightest a pen stroke can be</td><td>12%</td></tr><tr><td><strong>Draw input</strong></td><td>Stylus and touch, or <strong>Stylus only</strong> (fingers then only zoom and move)</td><td>Stylus and touch</td></tr><tr><td><strong>Stylus hover preview</strong></td><td>Shows the brush or eraser size as a circle while a pen hovers over the screen</td><td>Off</td></tr><tr><td><strong>Eraser outline</strong></td><td>Shows the eraser&#39;s size as a circle while you erase</td><td>On</td></tr></tbody></table><h2 id="canvas-gestures" tabindex="-1">Canvas &amp; gestures <a class="header-anchor" href="#canvas-gestures" aria-label="Permalink to &quot;Canvas &amp; gestures&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th><th>Default</th></tr></thead><tbody><tr><td><strong>Smooth zoom</strong></td><td>Lines stay crisp when you zoom in close (Android 13+). Turn off to see the real pixels</td><td>On</td></tr><tr><td><strong>Canvas rotation</strong></td><td>Twist with two fingers to rotate the canvas</td><td>On</td></tr><tr><td><strong>Tap gestures</strong></td><td>Two-finger tap to undo, three-finger tap to redo</td><td>On</td></tr><tr><td><strong>Haptic feedback</strong></td><td>Small vibrations on some buttons</td><td>On</td></tr><tr><td><strong>Left-handed toolbar</strong></td><td>Moves the tool options pill to the left edge</td><td>Off</td></tr><tr><td><strong>Keep screen on</strong></td><td>The screen stays on while a project is open</td><td>On</td></tr></tbody></table><h2 id="sound" tabindex="-1">Sound <a class="header-anchor" href="#sound" aria-label="Permalink to &quot;Sound&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th><th>Default</th></tr></thead><tbody><tr><td><strong>Sound while animating</strong></td><td>Each frame&#39;s sound plays as you step through frames, a note marks the frames a beat falls on, and the sound wave stays up while playing (see <a href="./sound">Sound</a>)</td><td>Off</td></tr></tbody></table><h2 id="projects" tabindex="-1">Projects <a class="header-anchor" href="#projects" aria-label="Permalink to &quot;Projects&quot;">​</a></h2><p><img src="'+a+'" alt="Project and about settings"></p><ul><li><strong>Default FPS</strong> — the speed new projects start with (12 fps).</li><li><strong>Autosave</strong> — how often your work is saved while you draw: every 5, 10 (default) or 30 seconds, every minute or every 2 minutes.</li></ul><h2 id="about" tabindex="-1">About <a class="header-anchor" href="#about" aria-label="Permalink to &quot;About&quot;">​</a></h2><ul><li><strong>Open-source licences</strong> — credits for the parts Toonik is built with, including the sound library.</li><li><strong>Reset settings</strong> — puts every setting back to its default. Your projects and movies are not touched.</li></ul>',18)])])}const w=s(i,[["render",h]]);export{b as __pageData,w as default};
